const sections: PrayerSection[] = [{"id":"eating-barachot-rishonot","heading":"Barachot Rishonot","group":"Eating","lines":[{"he":"לפני אכילת לחם נוטל את ידיו ואומר: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו, וְצִוָּנוּ עַל נְטִילַת יָדָים:","en":"Praised are You, Lord our God, Ruler of the universe, who made us holy with the Divine commandments and commanded us regarding the washing of hands.","note":true},{"he":"על הלחם מברך: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ:","en":"Praised are you, Lord our G-d, Ruler of the universe, who brings forth bread from the earth.","note":true},{"he":"על תבשיל מחמשת מיני דגן ועל מיני מאפה מברך: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא מִינֵי מְזוֹנוֹת:","note":true},{"he":"על היין מברך: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא פְּרִי הַגָּפֶן:","note":true},{"he":"על כל פרי העץ מברך: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא פְּרִי הָעֵץ:","note":true},{"he":"על פרי האדמה מברך: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא פְּרִי הָאֲדָמָה:","note":true},{"he":"על בשר ודגים. חלב וביצה וגבינה. כמהין ופטריות וכדומה. גם על המשקים חוץ מיין אומר: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ:","note":true}]},{"id":"eating-brachot-achronot-al-hamichyah","heading":"Al Hamichyah","group":"Eating · Brachot Achronot","lines":[{"he":"בָּרוּךְ אַתָּה יְיָ, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם,"},{"he":"על חמשת מיני דגן—עַל הַמִּחְיָה וְעַל הַכַּלְכָּלָה","note":true},{"he":"על היין—עַל הַגֶּפֶן וְעַל פְּרִי הַגֶּפֶן","note":true},{"he":"על פירות משבעת המינים—עַל הָעֵץ וְעַל פְּרִי הָעֵץ","note":true},{"he":"וְעַל תְּנוּבַת הַשָּׂדֶה וְעַל אֶרֶץ חֶמְדָּה טוֹבָה וּרְחָבָה שֶׁרָצִיתָ וְהִנְחַלְתָּ לַאֲבוֹתֵינוּ לֶאֱכוֹל מִפִּרְיָהּ וְלִשְׂבּוֹעַ מִטּוּבָהּ. רַחֵם (נָא) יְיָ אֱלֹהֵינוּ עַל יִשְׂרָאֵל עַמֶּךָ וְעַל יְרוּשָׁלַיִם עִירֶךָ וְעַל צִיּוֹן מִשְׁכַּן כְּבוֹדֶךָ, וְעַל מִזְבְּחֶךָ, וְעַל הֵיכָלֶךָ. וּבְנֵה יְרוּשָׁלַיִם עִיר הַקּדֶשׁ בִּמְהֵרָה בְיָמֵינוּ. וְהַעֲלֵנוּ לְתוֹכָהּ וְשַׂמְּחֵנוּ בְּבִנְיָנָהּ, וְנֹאכַל מִפִּרְיָּהּ וְנִשְׂבַּע מִטּוּבָהּ וּנְבָרֶכְךָ עָלֶיהָ בִּקְדֻשָּׁה וּבְטָהֳרָה. בשבת: וּרְצֵה וְהַחֲלִיצֵנוּ בְּיוֹם הַשַׁבָּת הַזֶּה. בר\"ח: וְזָכְרֵנוּ לְטוֹבָה בְּיוֹם רֹאשׁ הַחֹדֶשׁ הַזֶּה. בר\"ה: וְזָכְרֵנוּ לְטוֹבָה בְּיוֹם הַזִּכָּרוֹן הַזֶּה. ביום טוב ובחוה\"מ: וְשַׂמְּחֵנוּ בְיוֹם בפסח: חַג הַמַּצּוֹת הַזֶּה, בשבועות: חַג הַשָּׁבוּעוֹת הַזֶּה, בסוכות: חַג הַסֻּכּוֹת הַזֶּה, בשמיני עצרת: שְׁמִינִי, חַג עֲצֶרֶת הַזֶּה, בְּיוֹם (טוֹב) מִקְרָא קֹדֶשׁ הַזֶּה. כִּי אַתָּה יְיָ טוֹב וּמֵטִיב לַכּל וְנוֹדֶה לְּךָ עַל הָאָרֶץ"},{"he":"על חמשת מיני דגן—וְעַל הַמִּחְיָה","note":true},{"he":"על היין—וְעַל פְּרִי גַפְנָהּ (בחו\"ל—וְעַל פְּרִי הַגָּֽפֶן)","note":true},{"he":"על פירות משבעת המינים—וְעַל פֵּרוֹתֶיהָ (בחו\"ל—וְעַל הַפֵּרוֹת)","note":true},{"he":"בָּרוּךְ אַתָּה יְיָ, עַל הָאָרֶץ"},{"he":"על חמשת מיני דגן—וְעַל הַמִּחְיָה (וי\"א גם וְעַל הַכַּלְכָּלָה).","note":true},{"he":"על היין—וְעַל פְּרִי גַפְנָהּ (בחו\"ל—וְעַל פְּרִי הַגָּֽפֶן).","note":true},{"he":"על פירות משבעת המינים—וְעַל פֵּרוֹתֶיהָ (בחו\"ל—וְעַל הַפֵּרוֹת).","note":true}]},{"id":"eating-brachot-achronot-borei-nefashot","heading":"Borei Nefashot","group":"Eating · Brachot Achronot","lines":[{"he":"על פירות האילן חוץ מז' מינים ופירות האדמה וירקות ועל כל המשקין ועל דבר שאין גידולו מן הארץ"},{"he":"אחרי האכילה אומר:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא נְפָשׁוֹת רַבּוֹת וְחֶסְרוֹנָן עַל כָּל מַה שֶׁבָּרָאתָּ לְהַחֲיוֹת בָּהֶם נֶפֶשׁ כָּל חָי בָּרוּךְ חֵי חַי הָעוֹלָמִים:"}]},{"id":"blessings-on-sights-sounds-and-smells","heading":"Blessings on Sights Sounds and Smells","lines":[{"he":"ברכות הריח:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, בּוֹרֵא מִינֵי בְשֹמִים:"},{"he":"ברכות *הראיה*:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, עוֹשֹה מַעֲשֹה בְּרֵאשִׁית:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁעָשֹה אֶת הָיַּם הַגָּדוֹל:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, זוֹכֵר הַבְּרִית וְנֶאֱמָן בְּרִיתוֹ וְקַיָּם בַּמַאֲמָרוֹ:"},{"he":"ברכות השמיעה:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, שׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, הַטּוֹב וְהַמֵּטִיב:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, דַּיַּן הָאֱמֶת:"},{"he":"ברכת הקשת: הרואה קשת צריך לברך ברכה זו, ואסור להסתכל בו:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, זוֹכֵר הַבְּרִית נֶאֱמָן בִּבְרִיתוֹ וְקַיָּם בְּמַאֲמָרוֹ:"},{"he":"על הברקים ועל הרעמים:"},{"he":"על הברקים מברך:"},{"he":"בָּרוּךְ עוֹשֹה מַעֲשֹה בְרֵאשִׁית:"},{"he":"על הרעמים מברך:"},{"he":"בָּרוּךְ שֶׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם:"}]}];

